const block = (type, options = {}) => ({ type, ...options });

const RAW_MATERIAL_STANDARD_GSM = 78;

function formatSpecNumber(value) {
  return Number.isInteger(value) ? String(value) : String(Number(value));
}

export function formatRawMaterialSpec(value) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";

  const compactRaw = raw.replace(/\s*[×xX＊*]\s*/gu, "×");
  const parts = raw.replace(/[×xX＊]/gu, "*").split("*").map((part) => part.trim());
  if (parts.length !== 3) return compactRaw;

  const numbers = parts.map((part) => {
    const matches = part.match(/\d+(?:\.\d+)?/gu) ?? [];
    return matches.length === 1 ? Number(matches[0]) : 0;
  });
  if (numbers.some((number) => !Number.isFinite(number) || number <= 0)) return compactRaw;

  const [first, second, lengthM] = numbers;
  const gramPattern = /(?:克重|克数|克|gsm|g\b)/iu;
  const widthPattern = /(?:宽幅|门幅|幅宽|宽度|宽|cm|厘米)/iu;
  const firstIsGram = gramPattern.test(parts[0]);
  const secondIsGram = gramPattern.test(parts[1]);
  const firstIsWidth = widthPattern.test(parts[0]);
  const secondIsWidth = widthPattern.test(parts[1]);
  let gramWeightGsm = 0;
  let widthCm = 0;

  if (firstIsGram && secondIsWidth) [gramWeightGsm, widthCm] = [first, second];
  else if (secondIsGram && firstIsWidth) [gramWeightGsm, widthCm] = [second, first];
  else if (first === RAW_MATERIAL_STANDARD_GSM && second !== RAW_MATERIAL_STANDARD_GSM) [gramWeightGsm, widthCm] = [first, second];
  else if (second === RAW_MATERIAL_STANDARD_GSM && first !== RAW_MATERIAL_STANDARD_GSM) [gramWeightGsm, widthCm] = [second, first];
  else if (first === RAW_MATERIAL_STANDARD_GSM && second === RAW_MATERIAL_STANDARD_GSM) [gramWeightGsm, widthCm] = [first, second];
  else return compactRaw;

  return `${formatSpecNumber(gramWeightGsm)}克*${formatSpecNumber(widthCm)}宽*${formatSpecNumber(lengthM)}米`;
}

const facts = (items, title = "") => block("facts", { title, items });
const alert = (title, text, tone = "info") => block("alert", { title, text, tone });
const list = (title, items, options = {}) => block("list", { title, items, ...options });
const form = (title, fields) => block("form", { title, fields });
const checklist = (title, items, options = {}) => block("checklist", { title, items, ...options });
const timeline = (title, items) => block("timeline", { title, items });
const evidence = (title, text, options = {}) => block("evidence", { title, text, ...options });
const decisionSummary = (options) => block("decision-summary", options);
const varianceSummary = (options) => block("variance-summary", options);
const financialSummary = (options) => block("financial-summary", options);

const task = (title, meta, badge, tone = "neutral", selected = false, options = {}) => ({
  title,
  meta,
  badge,
  tone,
  selected,
  ...options,
});

const field = (label, value, type = "text", options = {}) => ({ label, value, type, ...options });
const semanticTag = (kind, value, label = "") => ({ kind, value, ...(label ? { label } : {}) });
const orderSemanticTags = (order) => [
  semanticTag("business", order.businessType),
  ...(order.requirements || []).map((value) => semanticTag("requirement", value)),
];
const orderTaskMeta = (order, extras = {}) => ({
  metaLead: orderMetaLead(order),
  semanticTags: orderSemanticTags(order),
  metaTail: extras.metaTail || orderQuantity(order),
  ...extras,
});
const orderIdentity = (order) => `${order.customer} · ${order.product}`;
const orderMetaLead = (order) => `${order.specification} · ${order.colorCombination}`;
const orderQuantity = (order) => `${new Intl.NumberFormat("zh-CN").format(order.quantity)} 个`;

