const decisionCase = ({
  id,
  title,
  badge,
  badgeTone = "warning",
  deadline,
  facts: factItems,
  summary,
  evidenceTitle,
  evidenceText,
  extraEvidenceBlocks = [],
  recommendation,
  decision,
  choices = [],
  reason,
  boundary,
  resultTitle,
  resultText,
  nextSteps,
  resultTarget,
  resultTargetRole,
}) => [
  {
    id: `${id}-evidence`,
    title,
    label: `${badge}依据`,
    icon: "file-search",
    status: deadline,
    statusTone: badgeTone,
    blocks: [
      summary || facts(factItems),
      evidence(evidenceTitle, evidenceText, { icon: "image", actionLabel: "查看证据" }),
      ...extraEvidenceBlocks,
      checklist("处理参考（系统测算）", recommendation, { readonly: true }),
      choices.length ? form("选择处理方式", [field("本次决定", decision, "select", { options: choices, decisionId: id })]) : null,
    ].filter(Boolean),
    primary: { label: "确认所选处理方式", target: `${id}-confirm` },
    secondary: { label: "返回待决定", target: "queue" },
  },
  {
    id: `${id}-confirm`,
    title: `确认${badge}决定`,
    label: `${badge}确认`,
    icon: "check-circle",
    status: "提交后决定生效",
    statusTone: "warning",
    blocks: [
      summary || facts(factItems, "决定依据快照"),
      block("decision-choice-confirmation", { decisionId: id, defaultDecision: decision }),
      form("决定说明", [field("处理依据", reason, "textarea")]),
      alert("提交后的边界", boundary, "warning"),
    ],
    primary: { label: "确认并生成执行待办", target: `${id}-result` },
    secondary: { label: "返回查看证据", target: `${id}-evidence` },
  },
  {
    id: `${id}-result`,
    title: `${badge}结果`,
    label: `${badge}结果`,
    icon: "check-circle",
    blocks: [
      block("decision-result", { decisionId: id, defaultDecision: decision, title: resultTitle, text: resultText, nextSteps }),
    ],
    primary: resultTargetRole
      ? { label: "查看下一角色接手", target: resultTarget, targetRole: resultTargetRole }
      : { label: "处理下一项", target: "queue" },
    secondary: { label: "查看决定历史", target: "history" },
  },
];

